/* Intermediate3 · ShopKaro private origins, cache variants and safe releases. */
(function(){
  const N=AG.aws.n,OPT='658327ea-f89d-4fab-a63d-7e88639e58f6',OFF='4135ea2d-6df8-44a3-9df3-4b5a84be39ad',FORWARD='b689b0a8-53d0-40ab-baf2-68738e2966ac',ID='ESHOP',BUCKET='shop-images',OAC='OAC000001';
  const control=()=>({Name:'shop-images-oac',Description:'ShopKaro S3 REST origin',OriginAccessControlOriginType:'s3',SigningBehavior:'always',SigningProtocol:'sigv4'});
  function config(){return {CallerReference:'shop-original',Comment:'ShopKaro catalog + API',Enabled:true,Origins:{Quantity:2,Items:[{Id:'images',DomainName:BUCKET+'.s3.ap-south-1.amazonaws.com',S3OriginConfig:{OriginAccessIdentity:''}},{Id:'api',DomainName:'api.shopkaro.in',CustomOriginConfig:{HTTPPort:80,HTTPSPort:443,OriginProtocolPolicy:'https-only',OriginSslProtocols:{Quantity:1,Items:['TLSv1.2']}}}]},DefaultCacheBehavior:{TargetOriginId:'images',ViewerProtocolPolicy:'redirect-to-https',CachePolicyId:OPT,Compress:true,TrustedKeyGroups:{Enabled:false,Quantity:0}},CacheBehaviors:{Quantity:1,Items:[{PathPattern:'/api/*',TargetOriginId:'api',ViewerProtocolPolicy:'https-only',CachePolicyId:OPT,AllowedMethods:{Quantity:7,Items:['GET','HEAD','OPTIONS','PUT','PATCH','POST','DELETE']},TrustedKeyGroups:{Enabled:false,Quantity:0}}]},Aliases:{Quantity:0},ViewerCertificate:{CloudFrontDefaultCertificate:true},PriceClass:'PriceClass_All'};}
  function fixed(){const c=config();c.Origins.Items[0].OriginAccessControlId=OAC;c.CacheBehaviors.Items[0].CachePolicyId=OFF;c.CacheBehaviors.Items[0].OriginRequestPolicyId=FORWARD;return c;}
  function policy(){return {Version:'2012-10-17',Statement:[{Effect:'Allow',Principal:{Service:'cloudfront.amazonaws.com'},Action:'s3:GetObject',Resource:'arn:aws:s3:::'+BUCKET+'/*',Condition:{StringEquals:{'AWS:SourceArn':'arn:aws:cloudfront::123456789012:distribution/'+ID}}}]};}
  function seed(){return {region:'ap-south-1',cloudfront:[{id:ID,domain:'dshop.cloudfront.net',enabled:true,status:'Deployed',etag:'E1',version:1,config:config(),edgeCache:[{path:'/img/kurta-red.jpg',version:'v1'}],invalidations:[]}],originAccessControls:[],buckets:[{name:BUCKET,public:false,encryption:true,bpa:{BlockPublicAcls:true,IgnorePublicAcls:true,BlockPublicPolicy:true,RestrictPublicBuckets:true},objects:[{key:'img/kurta-red.jpg',version:'v2',size:100000,cacheControl:'public,max-age=86400'}]}]};}
  const file=v=>({content:JSON.stringify(v,null,2)}),dist=s=>(s.account.cloudfront||[]).find(d=>d.id===ID),bucket=s=>(s.account.buckets||[]).find(b=>b.name===BUCKET);
  function preserved(s){const d=dist(s),b=bucket(s);return !!d&&d.domain==='dshop.cloudfront.net'&&(s.account.cloudfront||[]).length===1&&!!b&&!b.public&&b.encryption&&Object.values(b.bpa||{}).length===4&&Object.values(b.bpa).every(x=>x===true)&&(b.objects||[]).some(o=>o.key==='img/kurta-red.jpg'&&o.version==='v2');}
  function deployed(s){const d=dist(s),c=d&&(d.deployedConfig||d.config),a=(s.account.originAccessControls||[]).find(a=>a.id===OAC);if(!c||!c.Origins||!c.DefaultCacheBehavior||!c.CacheBehaviors)return false;const api=(c.CacheBehaviors.Items||[])[0];return c.Enabled&&d.status==='Deployed'&&c.CallerReference==='shop-original'&&c.Origins.Quantity===2&&(c.Origins.Items||[]).some(o=>o.Id==='images'&&o.DomainName===BUCKET+'.s3.ap-south-1.amazonaws.com'&&o.OriginAccessControlId===OAC&&o.S3OriginConfig&&!o.S3OriginConfig.OriginAccessIdentity)&&(c.Origins.Items||[]).some(o=>o.Id==='api'&&o.DomainName==='api.shopkaro.in'&&o.CustomOriginConfig&&o.CustomOriginConfig.OriginProtocolPolicy==='https-only')&&c.DefaultCacheBehavior.TargetOriginId==='images'&&c.DefaultCacheBehavior.CachePolicyId===OPT&&['redirect-to-https','https-only'].includes(c.DefaultCacheBehavior.ViewerProtocolPolicy)&&c.DefaultCacheBehavior.TrustedKeyGroups&&!c.DefaultCacheBehavior.TrustedKeyGroups.Enabled&&c.DefaultCacheBehavior.TrustedKeyGroups.Quantity===0&&(!c.DefaultCacheBehavior.TrustedSigners||!c.DefaultCacheBehavior.TrustedSigners.Enabled)&&c.CacheBehaviors.Quantity===1&&!!api&&api.PathPattern==='/api/*'&&api.TargetOriginId==='api'&&['https-only','redirect-to-https'].includes(api.ViewerProtocolPolicy)&&api.CachePolicyId===OFF&&api.OriginRequestPolicyId===FORWARD&&api.AllowedMethods&&Array.isArray(api.AllowedMethods.Items)&&api.AllowedMethods.Items.includes('POST')&&!!a&&a.config.SigningBehavior==='always'&&a.config.SigningProtocol==='sigv4'&&a.config.OriginAccessControlOriginType==='s3'&&(s.account.originAccessControls||[]).length===1;}
  function scopeOK(s){const b=bucket(s),p=b&&b.policy,t=p&&p.Statement;return Array.isArray(t)&&t.length===1&&t[0].Effect==='Allow'&&t[0].Principal&&t[0].Principal.Service==='cloudfront.amazonaws.com'&&t[0].Action==='s3:GetObject'&&t[0].Resource==='arn:aws:s3:::'+BUCKET+'/*'&&t[0].Condition&&t[0].Condition.StringEquals&&(t[0].Condition.StringEquals['AWS:SourceArn']||t[0].Condition.StringEquals['aws:SourceArn'])==='arn:aws:cloudfront::123456789012:distribution/'+ID;}
  const fresh=s=>{const d=dist(s),r=AG.cdnResponse(s.account,d,'/img/kurta-red.jpg');return r.status===200&&r.version==='v2'&&!(d.edgeCache||[]).some(e=>e.path==='/img/kurta-red.jpg');};
  const SOLUTION=['aws cloudfront create-origin-access-control --origin-access-control-config file://oac.json','aws cloudfront update-distribution --id ESHOP --if-match E1 --distribution-config file://distribution-fixed.json','aws cloudfront wait distribution-deployed --id ESHOP','aws s3api put-bucket-policy --bucket shop-images --policy file://origin-policy.json',"aws cloudfront create-invalidation --distribution-id ESHOP --paths '/img/kurta-red.jpg'",'aws cloudfront wait invalidation-completed --distribution-id ESHOP --id I000001'];
  function plan(k){const req=k.requests*1e6,variants=[1,20,200][k.key],misses=k.days===0?req:Math.min(req,1000*20*variants*Math.ceil(30/k.days)),hit=1-misses/req,freshSeconds=k.versioned?300:k.days*86400,gross=req*0.0001*0.085+req/10000*0.01+misses/1000*0.0004;return {req,misses,hit,freshSeconds,gross,p50:hit>=0.5?25:200,ok:k.requests>=20&&hit>=0.90&&freshSeconds<=300};}
  function Q(q,correct,wrong,answer,explain,domain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain,domain};}
  AG.registerLevels('intermediate',[{
    id:'cloudfront',icon:'🌍',title:'CloudFront: private origin, cache key aur naya release',badge:'Edge Engineer',
    hook:{when:'ShopKaro · photos wala bada launch · course ki kahani (fictional)',title:'"Chennai mein photo der se, aur sale ke baad bhi purane daam wali photo!"',text:'Priya ke test mein Chennai aur Guwahati mein product photos 2–3 second le rahi hain; yeh numbers course ki kahani ke hain, AWS ka vaada nahi. Ravi ne CDN lagaya. Par same photo URL par nayi file daalne ke baad bhi purana sale artwork dikh raha hai. Bucket private karte hi nayi requests par 403 aane laga. Speed (cache), bucket ki permission aur nayi file dikhna: teeno ka fix alag hai.'},
    objectives:['<b>Trace</b>: edge hit/miss, regional cache aur origin par load samjho','<b>Bachao</b>: S3 REST origin + OAC + sirf is distribution wali policy (SourceArn) + BPA','<b>Safe cache</b>: key mein kya daalna hai, TTL, API ko cache se bahar rakhna aur forwarding chuno','<b>Release</b>: naye naam wali files vs invalidation; browser cache ki limit pehchano','<b>Review</b>: HTTPS, signed viewer access, edge functions aur pricing mode compare karo','<b>Repair</b>: config/ETag update, deployment aur poori hui eviction ko state se check karo'],
    steps:[
      {q:'CDN origin se har photo baar-baar kyun nahi maangta?',analogy:'Har packet Jaipur ke warehouse se bhejne ki jagah, mohalle ki kirana dukaan thoda stock rakhti hai. Stock dukaan mein mil gaya (hit), toh paas ke customer ko warehouse tak ka chakkar nahi lagta. Naya maal pehli baar warehouse se hi aata hai.',body:'<pre>Viewer → CloudFront PoP\n  hit → cached response\n  miss → eligible regional edge cache\n       → origin fetch → cache → response</pre>',points:['AWS ke aaj ke overview mein 750+ Points of Presence (PoP) likhe hain. PoP, shehar aur building ki ginti ek cheez nahi. Sabse paas ke shehar ya fixed 20 ms ki koi guarantee nahi; routing aur cache garam hai ya nahi, isse latency badalti hai.','Hit ratio = cache se mili requests / cache ho sakne wali requests. Miss, expire, eviction, revalidation aur cache na hone wale paths origin ka traffic badhate hain. PoP ka cache hamesha ki copy nahi hai.','Maana hua example: 2 crore photo requests/mahina, 95% hits → origin tak sirf 10 lakh requests, 2 crore nahi. Par viewer tak bytes phir bhi jaate hain; cache hit se viewer ka data transfer free nahi hota.'],asli:'Kaam: dry run mein pehla fetch (miss) aur doosra (hit) compare karo. Diagram ka time sirf example hai; lab11 asli HTTP latency ya hit ratio nahi naapta.'},
      {q:'Distribution mein path, cache key aur aage bhejne wala data kaun tay karta hai?',analogy:'Delivery board ke route rules, stock ka label aur warehouse ko bheja note: teen alag kaagaz hain. Note mein customer ki har detail likhne ka matlab yeh nahi ki woh stock label ka hissa bane.',body:'<div class="tbl-wrap"><table><tr><th>Control</th><th>Kaam</th><th>Example</th></tr><tr><td>Origin</td><td>Content kahan se aata hai</td><td>S3 REST, ALB, API/custom origin</td></tr><tr><td>Ordered cache behavior</td><td>Pehla match hone wala path rule aur target</td><td>/api/* default photos se pehle</td></tr><tr><td>Cache policy</td><td>TTL ki limits + key ke headers/cookies/query</td><td>Public files kam variants mein reuse</td></tr><tr><td>Origin request policy</td><td>Extra values origin ko bhejo, key mein daale bina</td><td>API ko zaroori auth/cookies/query</td></tr><tr><td>Response headers policy</td><td>Jawaab ke security/CORS headers</td><td>Origin ki permission nahi deta</td></tr></table></div><p class="muted">Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p>',points:['Key mein daali values origin ko apne aap jaati hain. Origin request policy extra values bhej sakti hai, bina naye variants banaye. Agar jawaab kisi value se badalta hai aur woh key mein nahi, toh galat ya kisi aur ka jawaab share ho sakta hai.','MinimumTTL>0 ho, toh origin ke no-cache/no-store/private kehne par bhi cache ho sakta hai. Managed CachingOptimized mein minimum 1 second, default 86400 second. Login wali API par aankh band karke reuse karna unsafe hai.','Managed CachingDisabled mein min/default/max TTL 0 hai. Par sirf CachingDisabled se Authorization/cookies/query aage nahi jaate. Review ki hui origin request policy aur origin ka Host/TLS contract bhi chahiye.'],asli:'Kaam: mission mein cat distribution-fixed.json chalao. Default photos CachingOptimized use karti hain; /api/* CachingDisabled aur saaf forwarding policy use karta hai. API origin ka TLS hostname contract maana gaya hai, runtime par test nahi hua.'},
      {q:'S3 private rahe aur CloudFront padh sake: teen links kaun se hain?',analogy:'Warehouse ka gate public ke liye band hai. Delivery van ka signed badge, approved delivery company, aur us branch ki exact permission: teeno match hone chahiye.',body:'<pre>S3 REST origin\n + attached OAC: always / sigv4 / s3\n + bucket Allow: cloudfront.amazonaws.com\n   Action s3:GetObject; exact object prefix\n   StringEquals AWS:SourceArn = distribution ARN\n + Block Public Access stays ON</pre>',points:['OAC banana aur use jodna alag kaam hain. OriginAccessControlId ko distribution ke origin mein jodo, aaj ke ETag se update karo, aur deployment poora hone do. OAI purana tareeka hai; naye S3 designs aksar OAC use karte hain.','S3 website endpoint ek custom HTTP origin hai; OAC/OAI website endpoint par kaam nahi karte. Private OAC design S3 REST origin use karta hai. Naye bucket ka default "Bucket owner enforced" ownership theek hai.','SSE-KMS wale origin ke liye KMS key policy mein bhi permission chahiye. Sirf OAC ya bucket policy KMS decrypt ki permission nahi deti. Yeh fixture/lab SSE-S3 use karta hai, taaki ek hi permission boundary rahe.','Bucket ko bachana aur viewer ki permission alag hain. Private S3 origin ke saath bhi public viewers CDN se photo dekh sakte hain. Premium viewers ke liye signed URL/cookie ya app ki permission alag se jodo.'],example:'<div class="war-story"><b>Galti jo sab karte hain:</b> CDN ka 403 BPA band karke theek karna. Pehle dekho: OAC ka link ya SourceArn missing, galat origin type, explicit Deny, aur KMS permission. Public bucket se log CDN ko bypass kar sakte hain.</div>',asli:'Kaam: triage record mein purane OAI principal ko compare karo. CloudFront service Principal + aaj ka SourceArn + sahi association chahiye. BPA sahi scoped OAC access ko block nahi karta.'},
      {q:'Har header/cookie/query ko cache key mein daalne se kya tootega?',analogy:'Ek hi laal kurte ke stock labels har tracking ID ke liye alag banaoge, toh shelf ka reuse gir jaayega. Par size ya rang se asli item badalta hai, toh label se size/rang hataane par galat item jaayega.',body:'<div class="tbl-wrap"><table><tr><th>Input</th><th>Key ka faisla</th><th>Galti hui toh</th></tr><tr><td>Sirf utm tracking</td><td>Jawaab same hai toh key se bahar</td><td>Bekaar variants, hit ratio kam</td></tr><tr><td>Photo ki width/format se bytes badalte hain</td><td>Saaf, kaam ka variant key mein</td><td>Galat size/format ki photo</td></tr><tr><td>User ka login/session wala jawaab</td><td>Shared cache band, ya review kiya secure design</td><td>Ek user ka data doosre ko</td></tr></table></div><p class="muted">Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p>',points:['Sabse chhoti sahi key chuno; aankh band karke sabse chhoti key nahi. Pehle jawaab ka matlab aur privacy, phir hit ratio.','Badi company ka maana hua example: 1,000 files × 20 active caches × 20 bekaar variants = 4,00,000 pehli baar bharne wale objects. Asli traffic mein yeh number alag hoga; yeh sirf samajhne ke liye hai, AWS benchmark nahi.','"All headers" policy se kharcha aur hit ki problem to hoti hi hai, secret wala data bhi aage ja sakta hai. Zaroori inputs check karo; personal content ko ek public key mein mat milao.'],asli:'Kaam: flowlab mein key None → +query → bahut saari values wala header/cookie mode badlo. Toy miss count badhta hai; goal mein demand fixed rehni chahiye aur freshness safe.'},
      {q:'Purane daam wala artwork kaise badlein: TTL, invalidation ya naya path?',analogy:'Purana catalog page usi shelf label ko padhta rahega. Naya label wala edition chhapo aur catalog ka pointer badlo. Yeh baar-baar shelf khaali karne se aasaan hai, aur rollback bhi aasaan.',body:'<div class="tbl-wrap"><table><tr><th>Choice</th><th>Kab use karein</th><th>Limit</th></tr><tr><td>Versioned filename</td><td>Aam releases; img/kurta.v2.jpg</td><td>HTML/manifest pointer jaldi badlo; browser ka pointer cache maayne rakhta hai</td></tr><tr><td>Invalidation</td><td>Same URL ka emergency fix</td><td>Completed hone tak wait; browser/office ka cache saaf nahi hota</td></tr><tr><td>Chhota TTL</td><td>Baar-baar badalne wala shared content</td><td>Origin par zyada requests; turant invalidation nahi</td></tr></table></div><p class="muted">Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p>',points:['Pay-as-you-go mein har mahine pehle 1,000 invalidation paths/tags ka koi extra charge nahi; uske baad lagbhag $0.005/path/tag (₹88/$1 par ₹0.44). Wildcard /* ek path gina jaata hai, par sab dobara bharne se origin par load badhta hai.','Sirf S3 VersionId se public URL nahi badalta. Versioned filename/path, ya key mein sahi version query, ek naya URL hai. Bucket versioning ko CDN release ke naam se mat milao.','CloudFront invalidation edge se purane bytes hata sakta hai, par browser apne purane max-age se phir bhi dikha sakta hai. Naya path + chhote samay wala HTML/manifest + client refresh ka niyam chahiye.'],example:'<div class="war-story"><b>Production mein aisa hota hai:</b> nayi file deploy hui, par 1 din ke liye cache hua purana HTML purani file ko point karta raha. File versioning sahi thi, phir bhi release dikha nahi. Pointer ka caching aur rollback ka order test karo.</div>',asli:'Kaam: main mission mein same-path emergency fix ke liye targeted invalidation aur completion waiter use hota hai. Planner ke aam release example mein lambe samay wali files + versioned paths + 300 second pointer freshness maani gayi hai.'},
      {q:'HTTPS aur viewer access ko OAC se alag kyun rakhein?',analogy:'Delivery van ka badge warehouse mein ghusne deta hai. Customer ki paid membership delivery ka haq deti hai. Sadak par encryption na membership ki jagah leta hai, na warehouse ki policy ki.',body:'<div class="tbl-wrap"><table><tr><th>Zaroorat</th><th>Kya chuno</th><th>Limit</th></tr><tr><td>Viewer ke liye apna HTTPS naam</td><td>Alternate domain + us-east-1 mein matching ACM cert</td><td>Origin ka certificate/hostname contract alag</td></tr><tr><td>Ek premium file</td><td>Permission check ke baad app CloudFront URL sign kare</td><td>Expiry/policy/key rotation; link leak ho sakta hai</td></tr><tr><td>Bahut saari restricted files</td><td>Signed cookies, trusted key groups</td><td>Cookie ka scope, client support aur permission phir bhi maayne rakhte hain</td></tr><tr><td>Seedha S3 par thodi der ka kaam</td><td>S3 presigned URL</td><td>Seedha S3, CloudFront edge ki permission nahi</td></tr></table></div><p class="muted">Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p>',points:['App ki private key viewer URL/cookie sign karti hai; CloudFront trusted public key group se check karta hai. Kaun paid member hai, yeh CloudFront khud tay nahi karta; yeh app ka kaam hai.','Shield Standard DDoS protection apne aap, bina extra charge ke milta hai. WAF ke web rules app level par filter jodte hain; daam plan par depend karta hai. Geo restriction desh ke andaaze se access rokta hai; yeh poora compliance ya data residency control nahi.','Default *.cloudfront.net certificate ke liye ACM request nahi chahiye. Viewer ka custom ACM certificate us-east-1 mein hona chahiye, par iska matlab yeh nahi ki S3/ALB origin bhi us-east-1 mein ho.'],asli:'Interview ka agla sawaal: kya private S3 + OAC se premium file sirf paid users ke liye ho jaati hai? Nahi. Viewer ki permission aur bucket bypass se bachav, dono boundaries alag design karo.'},
      {q:'Dynamic API, private ALB aur edge code ke liye CloudFront theek hai?',analogy:'Paas ka delivery desk sirf rakhe hue parcels nahi deta; naye custom orders ka encrypted connection bhi sambhalta hai. Label ka chhota badlav aur warehouse par tika hua hisaab: dono ke liye alag machinery chahiye.',body:'<div class="tbl-wrap"><table><tr><th>Choice</th><th>Kab</th><th>Limit</th></tr><tr><td>CloudFront /api/*</td><td>HTTP API ke liye edge TLS, WAF; review ki hui no-cache/forwarding</td><td>POST/auth origin/app par phir bhi test; dynamic content ko cache ke bina bhi fayda</td></tr><tr><td>CloudFront Functions</td><td>Viewer request/response ka chhota JS rewrite</td><td>10 KB code, 2 MB memory; network/body access nahi; runtime 2.0 mein KVS milta hai</td></tr><tr><td>Lambda@Edge</td><td>Bhaari viewer/origin logic, network/body chahiye</td><td>Alag runtime/quotas/kharcha; event ki restrictions check karo</td></tr><tr><td>VPC origin</td><td>Supported private ALB/NLB/EC2 origin</td><td>Supported region/features, ENI/SG/deployment ki zarooratein check karo</td></tr></table></div><p class="muted">Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p>',points:['CloudFront ab private VPC origins support karta hai; "sirf public ALB chalega" wali baat purani hai. Yeh level lab mein sirf S3 ka data dekhta hai; VPC origin ka network runtime test nahi hua.','Non-HTTP TCP/UDP ke saath fixed global entry/failover chahiye, toh Global Accelerator dekho. CloudFront mein HTTP ke liye optional Anycast Static IP lists bhi ab hain; aam distribution DNS aur yeh paid IP feature alag pehchano.','Origin request policy agar viewer ka Host aage bhejti hai, toh origin ka TLS ya app routing match nahi bhi ho sakta. Is API fixture mein api.shopkaro.in contract review ke baad AllViewerExceptHostHeader maana gaya hai; iske managed use cases mein API Gateway/Lambda URLs aate hain. Production ALB ke header/authorization alag se check karo.'],asli:'Kaam: cat distribution-fixed.json mein /api/* ka target api + CachingDisabled dekho. API forwarding ka sahi data hone se auth/session ka jawaab sahi hai, yeh prove nahi hota.'},
      {q:'Hit ratio zyada ho toh viewer bandwidth ka bill bhi lagbhag zero ho jaata hai?',analogy:'Warehouse ke chakkar kam hue, par local delivery van customers tak utne hi parcels le jaati hai. Warehouse ka load bachna aur viewer tak delivery ka kharcha: do alag meter hain.',body:'<p>Pay-as-you-go: US/commercial pehle tier ka example, lagbhag $0.085/GB viewer data transfer (DTO) aur $0.010 har 10,000 HTTPS requests. Jagah aur tier se daam badalte hain. Har mahine eligible billing scope mein 1 TB viewer DTO aur 1 crore HTTP(S) requests free milte hain. AWS origin se CloudFront tak ka fetch free hai; S3 GET/storage/KMS ka charge phir bhi lagta hai.</p>',points:['Ab flat-rate plans bhi hain: har distribution ka mahine ka bundle, jisme kuch WAF/DNS/compute/storage features hote hain. Pay-as-you-go ke toy hisaab ko flat-rate ka bill mat bolo; plan ki allowance, features aur aaj ki shartein check karo.','Aam pay-as-you-go mein disabled distribution ki koi $50/mahina "edge reservation" fees nahi hoti. Requests/transfer ruk jaate hain; par judi storage, subscriptions, dedicated features ya plan ka kharcha reh sakta hai.','Price classes kuch mehenge edge regions ko bahar rakhti hain: thodi latency/coverage ke badle kam kharcha. Origin alag rehta hai. "Class100 = sabse saste users" ya sabse paas ke shehar ki latency ki koi guarantee nahi.','Flowlab free allowance/discount/plans se pehle ka kul kharcha dikhata hai: har response 100 KB, US pehle tier ke daam + S3 GET lagbhag $0.0004/1,000. ₹88 = $1. WAF, logging, edge compute, baaki storage aur tax alag.'],asli:'Kaam: cache hit ratio badhao. Model mein origin GETs kam hote hain, par viewer bytes aur CDN delivery ka charge rehta hai. Card ke numbers lagbhag list rates hain (check kiye hue); planner ke workload aur latency course ke maane hue numbers hain.'},
    ],
    myth:[{myth:'CDN hamesha 20 ms deta hai aur viewer egress 10× sasta hone ki guarantee hai.',sach:'PoP ka chunav, network aur hit ratio badalte rehte hain. Origin ka load kam ho sakta hai; par viewer tak bytes jaate hain aur chune hue plan/rate se charge hote hain.'},{myth:'OAC bana diya, toh bucket private bhi ho gaya aur paid viewer ki permission bhi ho gayi.',sach:'OAC jodna, scoped bucket/KMS permissions aur deployment chahiye. Signed viewer access/permission ek alag boundary hai.'},{myth:'Saare headers key mein daalna sabse safe hai; minimum TTL ke saath no-store matlab cache nahi hoga.',sach:'Jinse jawaab badalta hai, wahi key mein chahiye; bekaar headers cache ko tukdon mein baant dete hain. MinimumTTL>0 private/no-store ko override kar sakta hai; sensitive APIs ke liye review kiya hua CachingDisabled lagao.'},{myth:'Invalidation browser ke caches saaf kar deta hai; disabled aam CDN ki $50/mahina reservation lagti hai.',sach:'Invalidation sirf CloudFront ki copies hataata hai, browser/office ke caches nahi. Aam distribution ki koi base reservation fees nahi; judi cheezon, features ya plans ka kharcha phir bhi ho sakta hai.'}],
    playbook:{title:'Kab use karein / kab nahi: cache aur release ka faisla',use:['Duniya bhar ke liye HTTP static/media, jo baar-baar maanga jaata hai','HTTP APIs jinhe edge TLS/WAF aur review ki hui forwarding chahiye, bina cache ke bhi','OAC aur saaf origin policy ke saath private S3 origin; viewer ki permission alag'],avoid:['Har user ke apne data ko ek shared public key mein cache karna','CDN ko TCP/UDP transport ya database replication samajhna','S3 website endpoint par OAC; 403 ke jugaad mein poora public access'],how:['Resource aur uski sensitivity likho; origin type aur jawaab kis cheez se badalta hai dekho','Ordered path behavior, sabse chhoti sahi key, TTL aur forwarding chuno','OAC jodo + exact distribution SourceArn wali policy; BPA on rakho; KMS ho toh uski permission check karo','Aam release ke liye versioned files + jaldi badalne wala manifest; same-path emergency ke liye targeted invalidation, Completed tak','Config/ETag padho, badlav merge karo, deployed hone tak wait; allowed ho toh asli clients dekho'],redflags:['Purana OAI Principal; galat SourceArn; OAC bana par juda nahi','API ko CachingOptimized mil gaya; safe design mein auth cookie chhoot gayi','Nayi photo upload hui par purana HTML pointer cache mein; InProgress invalidation ko poora maan liya','Cache hit ratio ko naapi gayi latency ya poore app ki permission ka saboot bolna'],rule:'Faisla kaise karein: HTTP hai? CloudFront socho. Har user ka alag jawaab? Shared cache band karo, auth review karo. Private S3 REST? OAC + scoped policy. Aam badlav? Versioned path + chhota pointer. Same URL ka emergency? Invalidate + wait; browser cache phir bhi maayne rakhta hai. Viewer ka chhota rewrite? Functions. Network/body/origin logic? Lambda@Edge dekho.'},
    exam:[{cue:'"global repeated static content"',pick:'CloudFront',why:'Edge cache origin ke eligible fetches kam karta hai; latency aur kharcha workload par depend.'},{cue:'"private S3 accessible via distribution only"',pick:'REST origin + OAC + SourceArn policy + BPA',why:'Sirf viewer signed URL public bucket ke bypass ko nahi rokta.'},{cue:'"one paid download" / "many protected files"',pick:'Signed URL / signed cookies with trusted key groups',why:'Pehle app ki permission; viewer ki permission OAC se alag hai.'},{cue:'"/api vs /img"',pick:'Ordered behaviors, CachingDisabled for selected API',why:'Zaroori auth/query/cookies aage bhejo aur Host contract check karo.'},{cue:'"custom CloudFront viewer ACM cert"',pick:'us-east-1',why:'Origin ka region/certificate alag faisla hai.'},{cue:'"same URL stale after overwrite"',pick:'Targeted invalidation + completion; prefer versioned releases',why:'CloudFront ka Completed browser ka cache saaf nahi karta.'},{cue:'"lightweight viewer header/URL rewrite"',pick:'CloudFront Functions',why:'Chhota JS viewer code; network ya request body ka access nahi.'},{cue:'"block countries or web exploits"',pick:'Geo restriction / WAF per requirement',why:'Shield Standard DDoS protection alag cheez hai; kanooni residency ki guarantee nahi.'},{cue:'"private ALB behind CloudFront"',pick:'Review supported VPC origin',why:'Yeh feature aaj hai; static IP/non-HTTP ki shart ho toh service soch kar chuno.'}],
    stages:[
      {type:'dryrun',title:'🔍 Ek photo: miss, hit, purani copy aur safe release',goal:'Har "Agla" click par cache ka ek badlav dekho. Origin ki permission aur browser freshness ke do faislon ka jawaab do.',nodes:[N('user',150,80,{label:'Chennai'}),N('cf',440,80,{label:'CloudFront PoP'}),N('cf#regional',800,80,{label:'Regional cache'}),N('iam',800,265,{label:'OAC / sigv4'}),N('s3',800,445,{label:'S3 REST / v2'}),N('cf#cache',440,445,{label:'Edge copy / v1'}),N('dev',150,445,{label:'Release pointer'})],edges:[{from:'user',to:'cf'},{from:'cf',to:'cf#regional'},{from:'cf#regional',to:'iam'},{from:'iam',to:'s3'},{from:'cf',to:'cf#cache'},{from:'dev',to:'user'}],panels:[{id:'fetch',title:'Source / permissions'},{id:'fresh',title:'Version / cache boundary'}],steps:[
        {clock:'miss',say:'Viewer /img/kurta-red.jpg maangta hai. Edge aur regional caches mein nahi mila (miss). Origin request ko juda hua OAC sigv4 se sign karta hai; bucket policy is distribution ke SourceArn ko allow karti hai. Diagram maanta hai ki OAC sahi hai; asli network latency nahi naapi gayi.',flows:[{from:'user',to:'cf',tone:'ok'},{from:'cf',to:'cf#regional',tone:'slow'},{from:'cf#regional',to:'iam',tone:'ok'},{from:'iam',to:'s3',tone:'ok'}],panels:{fetch:['REST origin + juda hua signing OAC + scoped policy','BPA stays ON'],fresh:['Maan lo public file ka TTL 86400 second hai']}},
        {clock:'hit',say:'Agla viewer same key maangta hai. Edge par v1 copy fresh hai, isliye origin tak nahi jaana padta. Viewer tak bytes phir bhi jaate hain. Hit ka matlab: cache wali copy ke liye origin ki permission dobara check nahi hoti.',flows:[{from:'cf',to:'cf#cache',label:'same key',tone:'ok'}],panels:{fetch:['Cache hit se origin request bach jaati hai'],fresh:['Key mein farak ho toh alag variants ban sakte hain']},ask:{q:'Naye miss par 403. Bucket private hai, OAC bana hai, par origin mein OAC ID nahi hai. Sahi repair?',choices:['OAC jodo aur scoped bucket policy lagao, deploy karo; Block Public Access on rakho','BlockPublicPolicy band karo aur saare objects public kar do, taaki origin ki error chhup jaaye','CloudFront viewer signed URL jodo, aur OAC ko S3 origin se bina jode chhod do','Sirf photo ka TTL kam karo, kyunki expire hone par CloudFront ko read permission mil jaati hai'],answer:0,explain:'OAC jodna aur permission theek karna missing origin access ko theek karta hai. Public jugaad bypass khol deta hai. Viewer signature aur TTL S3 origin ki permission nahi dete.'}},
        {clock:'overwrite',say:'Ravi usi S3 key par artwork v2 upload karta hai. Edge ki v1 copy abhi TTL ke andar fresh hai. S3 ki sabse nayi file aur CloudFront ka abhi ka jawaab alag ho sakte hain.',panels:{fresh:['Origin par version=v2; cache wala jawaab=v1','Sirf S3 versioning se CDN ka naya URL nahi banta']}},
        {clock:'emergency',say:'Targeted invalidation bani, status InProgress hai. Bhejne ko poora hona mat gino. Completed hone ke baad agla miss allowed origin se v2 layega.',nodes:{'cf#cache':{tone:'warn',badge:'v1 until complete'}},panels:{fetch:['Naye config ka deployment aur invalidation alag states hain'],fresh:['InProgress ≠ Completed']}},
        {clock:'routine release',say:'Agla release /img/kurta.v3.jpg publish karo; HTML/manifest ka pointer badlo. Purane HTML pointer ke cache ka time bandhe bina sirf file versioning se 5 minute mein dikhne ki guarantee nahi.',flows:[{from:'dev',to:'user',label:'new path pointer',tone:'ok'}],ask:{q:'Versioned files ke baad bhi purane daam wali photo 1 din tak dikh rahi hai. Sabse achha agla kadam?',choices:['Purana HTML/manifest ya app ka pointer cache dekho; pointer aur freshness ka niyam badlo','S3 bucket delete karo, kyunki versioned filenames ke liye public website endpoint chahiye','Bekaar cookie/header ke cache variants badhao jab tak purana browser pointer na hat jaaye','OAC dobara banao, kyunki origin signing har browser ko apne aap refresh karwata hai'],answer:0,explain:'Purana pointer abhi bhi purani file dikhata hai. Bucket delete karna, bekaar key variants aur duplicate OAC browser ka HTML saaf nahi karte; chhota pointer cache ya client refresh chahiye.'},panels:{fresh:['Versioned path purani file ke URL caches ko bypass karta hai','Browser/office ke caches CloudFront se saaf nahi hote']}},
        {clock:'review',say:'Teen checks: origin se kaun le sakta hai, key kis jawaab ko pehchanti hai, aur clients ko naya URL kab pata chalta hai. DNS/ETag/Deployed ka data HTTP recovery ka naap nahi hai.',panels:{fetch:['OAC origin ki permission ≠ viewer ki permission'],fresh:['Client ke asli jawaab ka version aur headers alag se naapo']}},
      ],lesson:'Same path par nayi file daalne se purane cache bytes reh sakte hain. Origin ki sahi permission, cache variant aur release pointer ki freshness: teeno alag faisle hain.'},
      {type:'flowlab',title:'🎛️ Cache reuse vs 5 minute mein release',goal:'Demand kam se kam 2 crore requests/mahina, hit ratio ≥90%, aur badlav ≤300 second mein dikhe. TTL, key ke inputs aur versioned release/pointer ka niyam chuno.',scenario:'Toy workload: 1,000 public files × 20 active caches; bekaar query variants 20, bahut saari values wale headers/cookies 200. 30 din barabar; miss = har variant/TTL cycle ki pehli bharai, demand se zyada nahi. Hit 25 ms, miss 200 ms (sirf do points ka toy model); p50 asli naap nahi. Versioned path + release/pointer refresh 300 second maana gaya. Har response 100 KB; US pehle tier ka CDN DTO $0.085/GB + HTTPS $0.010/10,000 + S3 GET $0.0004/1,000; free allowance, plans aur baaki fees bahar; ₹88 = $1.',knobs:[{id:'days',label:'Public asset TTL',min:0,max:7,step:1,value:0,unit:' days'},{id:'key',label:'Key variant inputs',min:0,max:2,step:1,value:2,labels:{0:'Only needed path',1:'+ tracking queries',2:'+ varied headers'}},{id:'requests',label:'Monthly demand',min:10,max:50,step:10,value:20,unit:' M/month'},{id:'versioned',label:'Versioned release',min:0,max:1,step:1,value:0,labels:{0:'Off',1:'On / 300s contract'}}],model:k=>{const b=plan(k);return {readouts:[{label:'Modeled hit ratio',value:(b.hit*100).toFixed(1)+'%',tone:b.hit>=0.90?'ok':'bad'},{label:'Modeled origin requests',value:b.misses.toLocaleString()+'/month',tone:'info'},{label:'Toy p50 latency',value:b.p50+' ms',tone:'info'},{label:'Modeled visibility',value:b.freshSeconds+' seconds',tone:b.freshSeconds<=300?'ok':'bad'},{label:'Lagbhag kul usage kharcha',value:'$'+b.gross.toFixed(2)+'/month · ₹'+Math.round(b.gross*88),tone:'info'}],verdict:{ok:b.ok,text:b.ok?'Toy budget pass. Asli cache headers, browser pointers, permission aur jagah ke hisaab se bill ke alag test chahiye.':'Example: TTL 1 din, sirf path ki key, 2 crore requests, versioned path On → 97% hits, 300 second mein dikhe; sensitive API ka cache alag se band rehta hai.'}};},check:k=>plan(k).ok,lesson:'2 crore requests, 1 din TTL aur sirf path ki key par: origin tak 6,00,000 requests, model mein 97% hits. Versioned path + jaldi pointer 300 second maana. Viewer ko 2,000 GB aur 2 crore HTTPS requests phir bhi jaate hain; free allowance/discount/plans se pehle lagbhag $190.24/mahina.'},
      {type:'bins',title:'🗂️ Content kitna sensitive → cache ka tareeka',instructions:'Jawaab kitna fresh chahiye aur kitna private hai, iske hisaab se chuno; sirf origin/public/private ke label se TTL tay nahi hota.',bins:[{id:'long',label:'Cache long'},{id:'short',label:'Cache short'},{id:'off',label:'No shared cache'}],items:[{text:'Hash wali app.8f3.js: public, kabhi na badalne wali release file',bin:'long',explain:'Lamba time + har release par naya filename; HTML pointer chhota/fresh.'},{text:'Version wala public product photo path',bin:'long',explain:'Har URL ke bytes pakke; public reuse safe.'},{text:'Public catalog HTML jo aaj ke release ko point karta hai',bin:'short',explain:'Chhoti pointer freshness release ko dikhne deti hai; exact TTL zaroorat se.'},{text:'Public stock summary jo har 30 second mein refresh hoti hai',bin:'short',explain:'Sirf tab jab thodi purani value chal jaaye; checkout stock ka pakka check karta hai.'},{text:'Login ke baad account balance ka jawaab',bin:'off',explain:'Shared cache band rakhne se ek user ka data doosre tak nahi jaata; auth sahi se aage bhejo.'},{text:'Checkout POST aur user session ka jawaab',bin:'off',explain:'Koi shared cache nahi; app ki permission aur idempotency phir bhi chahiye.'}]},
      {type:'match',title:'🔑 Permission tool → uski exact boundary',instructions:'Origin access, CDN viewer access aur seedha S3 access ko mat milao.',pairs:[{left:'CDN se ek premium file, app ki permission ke baad',right:'CloudFront signed URL',explain:'App trusted key se sign karta hai; CloudFront viewer policy check karta hai.'},{left:'CDN se bahut saari protected files, app ki permission ke baad',right:'CloudFront signed cookies',explain:'Policy/cookie ka scope + trusted key group; khud se origin ki permission nahi.'},{left:'Seedha S3 object par thodi der ka kaam',right:'S3 presigned URL',explain:'Seedhi S3 request; CloudFront cache ya viewer policy beech mein nahi.'},{left:'CloudFront service private S3 REST origin se pehchaan karwata hai',right:'OAC + scoped bucket policy',explain:'Juda hua signing OAC aur exact SourceArn; viewer phir bhi public ho sakta hai.'}]},
      {type:'triage',title:'🩺 Bucket private karne ke baad CDN par 403',symptom:'Nayi /img/new.jpg request par 403. Distribution par OAC juda hai, Deployed hai, aur SSE-S3 object bana hua hai. Par bucket policy abhi bhi purane OAI principal ko allow karti hai. Yeh saboot fixtures hain; Moto mein HTTP request nahi naapi gayi.',commands:[{cmd:'aws cloudfront get-distribution-config --id ESHOP',out:'{"ETag":"E2","DistributionConfig":{"Origins":{"Items":[{"Id":"images","DomainName":"shop-images.s3.ap-south-1.amazonaws.com","OriginAccessControlId":"OAC000001","S3OriginConfig":{"OriginAccessIdentity":""}}]}}}',clue:true,note:'OAC juda hai; purana OAI origin use nahi karta.'},{cmd:'aws s3api get-bucket-policy --bucket shop-images',out:'{"Statement":[{"Effect":"Allow","Principal":{"AWS":"arn:aws:iam::cloudfront:user/CloudFront Origin Access Identity EOLD"},"Action":"s3:GetObject","Resource":"arn:aws:s3:::shop-images/*"}]}',clue:true,note:'Purana OAI principal CloudFront service ki OAC requests ko aaj ke SourceArn ke saath allow nahi karta.'},{cmd:'aws s3api get-public-access-block --bucket shop-images',out:'{"PublicAccessBlockConfiguration":{"BlockPublicAcls":true,"IgnorePublicAcls":true,"BlockPublicPolicy":true,"RestrictPublicBuckets":true}}',clue:false,note:'BPA on rehna chahiye; sahi scoped service principal policy public jugaad nahi hai.'},{cmd:'aws cloudfront get-distribution --id ESHOP',out:'{"Distribution":{"Status":"Deployed","DistributionConfig":{"Enabled":true,"ViewerCertificate":{"CloudFrontDefaultCertificate":true}}}}',clue:false,note:'Is scenario mein default viewer TLS chal raha hai; origin ki permission missing hai, custom cert ki dikkat nahi.'}],questions:[Q('Naye object par 403 ki sabse mazboot wajah?','Bucket ka allow purane OAI principal ka hai, jabki origin ab OAC service requests bhejta hai',['Chaaron BlockPublicAccess flags har CloudFront service principal policy ko reject karte hain','Default CloudFront certificate ko origin region ke ACM certificate se badalna zaroori hai','1 din ka cache TTL anonymous writes deta hai par signed S3 read requests rok deta hai'],0,'Purani OAI policy aaj ke OAC service ko access nahi deti. Scoped OAC BPA ke saath chalta hai; viewer cert alag hai; TTL S3 ki koi permission nahi deta.','secure'),Q('Origin ko private rakhte hue repair kya hai?','Object prefix par service ko GetObject allow karo, aaj ke distribution SourceArn ke saath',['Bucket public karo aur SourceArn hata do, kyunki OAC private S3 use nahi kar sakta','CloudFront viewers ko EC2 instance profile do, taaki woh temporary IAM keys reuse karein','/img ki key mein har Authorization header daalo, taaki policy ka principal khud badal jaaye'],1,'Scoped service Allow OAC ki origin permission theek karta hai; BPA on rehta hai. Public bucket bypass kholta hai; viewers EC2 roles nahi lagate; cache key IAM policy edit nahi karti.','secure')]},
      (function(){const tasks=[{text:'Purana distribution deployed/enabled; signing S3 OAC juda; /api/* bina cache ke, review ki hui forwarding ke saath',check:deployed},{text:'Sirf is distribution ke liye service ka GetObject bucket allow; koi public access nahi',check:scopeOK},{text:'Naya fixture fetch origin se v2 laata hai; purani same-path edge entry sirf Completed ke baad hati',check:fresh},{text:'Purana distribution/origins/object/BPA bache rahe; koi extra OAC nahi',check:preserved}];return {type:'terminal',title:'🖥️ Mission: private origin aur same-path emergency refresh',instructions:'Pehle dekho: aws cloudfront get-distribution-config --id ESHOP. ETag E1 padho aur cat distribution-fixed.json chalao; yeh JSON poora merged config hai, patch nahi. ls/cat se teen mission files dekho. Chhe state badalne wale commands chahiye; OAC000001 aur I000001 pehle se tay hain.',goal:'ESHOP/dshop.cloudfront.net enabled rakho. always/sigv4 S3 OAC jodo, /api/* CachingDisabled + forwarding wala sahi poora config lagao, deployed hone tak wait karo, aur BPA ON rakhte hue sirf ESHOP SourceArn ko GetObject allow karo. Origin par img/kurta-red.jpg=v2 hai par edge fixture=v1; targeted invalidation Completed honi chahiye. Bucket/distribution delete karna, public jugaad, galat policy ya sirf pending edits se jeet nahi milegi. Fixture model ka status/version deta hai, asli HTTP nahi.',account:seed(),files:{'oac.json':file(control()),'distribution-fixed.json':file(fixed()),'origin-policy.json':file(policy())},tasks,success:AG.allOf(tasks),solution:SOLUTION.slice(),hints:SOLUTION.map((c,i)=>c+[' — ishara: pehle signing identity banao; jodna alag kaam hai',' — pehle config/ETag lo; E1 sirf pehle update tak valid hai',' — dhyaan do: InProgress config abhi deployed serving state nahi hai',' — exact SourceArn aur service Principal; origin private hi rahe',' — same URL ka emergency fix; bhejne par status InProgress hota hai',' — aakhri eviction Completed; ab serving fixture v2 padhta hai'][i]),successText:'Private origin ka config, scoped permission, API ka cache bypass aur poori hui targeted eviction: sab match karte hain. Fixture ka status 200 / version v2 saved state se nikla hai, AWS ka naapa hua HTTP nahi. Asli auth, KMS/TLS, browser caches aur app latency ke alag runtime test chahiye.'};})(),
      {type:'docker',title:'🐳 Lab11: asli CLI, aur emulator ki kamiyan saaf-saaf',project:'11-cloudfront-oac',goal:'README ke ex1–ex5: JSON/ETag dekho → OAC banao/update request → scoped policy/BPA → invalidation ka data → cleanup. OAC link ka readback null aaye matlab check nahi hua, private delivery pass nahi.',why:'Asli CLI ke fields ka syntax aur data ki kamiyan debug karna seekho; Moto ka accept karna asli OAC auth ya ETag concurrency ka certificate nahi.',steps:[{text:'README Setup ke exports chalao, phir lab ka bucket/object/distribution banao.',cmd:'cd aws-gurukul/docker-labs\n./start-moto.sh\nsource env.sh\ncd 11-cloudfront-oac\n# README Setup exports run karo.\nbash setup.sh\nsource .lab/resources.sh',expect:'Enabled=true; bana hua S3 REST origin aur wapas aaya ETag.'},{text:'OAC banao, ETag padho, update aur scoped bucket policy bhejo. OAC ka readback null aaye toh imaandari se likho.',cmd:'bash exercises.sh\nsource .lab/resources.sh',expect:'Status=Deployed par abhi ke Moto mein OAC=null; BPA sab true; policy mein exact distribution SourceArn save hai.'},{text:'Sirf data dekho. Abhi ke Moto mein status uppercase hai, isliye invalidation-completed waiter mat chalao.',cmd:'aws cloudfront get-invalidation --distribution-id "$DIST" --id "$INVALIDATION"',expect:'Moto mein Status="COMPLETED"; AWS ka standard status Completed hai. Asli edge eviction nahi naapi gayi.'},{text:'Config aur aaj ke ETag se disable karo, deployed hone tak wait karo, sirf save kiye resources delete karo.',cmd:'bash cleanup.sh',expect:'pehle false, phir distribution/OAC/bucket ki matching ginti 0/0/0.'}],observe:Q('Moto purana (STALE) ETag bhi maan leta hai aur OAC=null padhta hai. Kya daava kar sakte hain?','CLI requests aur scoped policy save hui; OAC jodna aur concurrency ki rok check nahi hui',['Poori private CDN permission aur asli duniya mein concurrent update ki sahi rok pakki hui','750 PoPs par nayi CDN photo ke bytes 300 second ki pakki window mein naape gaye','AWS ka OAC field galat hai, kyunki abhi ka emulator use chupchaap gira deta hai'],2,'Emulator ki kamiyon se saboot kam ho jaata hai. Asli CDN, probes ya concurrency ka saboot nahi; adhoora emulator sahi AWS fields bhi gira sakta hai.','secure')},
      {type:'quiz',title:'📝 Bonus: CDN ke trade-offs, bina naaron ke',questions:[
        Q('Private S3 REST origin, OAC bana hai, phir bhi naye fetch par 403. Config ka pehla saboot kya dekhoge?','OriginAccessControlId juda hai ya nahi, scoped bucket SourceArn policy aur deployment',['Sirf viewer signed URL ki length aur CloudFront invalidation quota, origin config chhod kar','EC2 ka public IP, kyunki har private S3 REST origin ko NAT ka inbound raasta chahiye','Bucket policy ya OAC link dekhne se pehle saare public-access controls band kar dena'],0,'Jodna, policy aur deployment origin access tay karte hain; SSE-KMS ho toh key permission bhi. Viewer token/quota ka lena-dena nahi; EC2 public IP nahi chahiye; public jugaad origin ki boundary tod deta hai.','secure'),
        Q('Chhoti public files ki cache key mein random tracking query hai. Kya asar hoga?','Zyada variants reuse kam karte hain, chahe andar ke bytes bilkul same hon',['Hit ratio apne aap badhega, kyunki har alag tracking key ek hi entry share karti hai','Origin GET ka saara kharcha hat jaayega, kyunki query strings kabhi origin tak nahi jaati','Har user ki pakki permission, kyunki random tracking input signed token ka kaam karta hai'],1,'Bekaar variants cache ko tukdon mein baant dete hain; alag values ki keys share nahi hoti. Key ke inputs origin tak jaate hain; tracking ki random value permission nahi hai aur GET ka charge nahi hataati.','high-performing'),
        Q('Naya hash wala file path deploy hua, par purana release dikh raha hai. Kya check karoge?','HTML/manifest pointer ka cache aur client refresh, phir asal mein maanga gaya file URL',['S3 VersionId, kyunki andar ka version badalne se saare CDN URLs pehle hi badal chuke hain','OAC SigningProtocol, kyunki sigv4 hamesha browser ke manifest cache ko refresh karwata hai','PriceClass, kyunki saare regions chunne se pointers ka browser cache-control override hota hai'],2,'Pointer abhi bhi purani file dikha sakta hai. S3 version URL ke naam se alag hai; OAC origin requests sign karta hai; price class browser cache saaf nahi karti.','high-performing'),
        Q('Premium course mein har viewer ke saikdon protected segments hain. Viewer ke liye sahi control?','App ki permission ke baad signed cookies, trusted key group aur private origin ke bachav ke saath',['Sirf OAC banao, viewer policy nahi, kyunki private origin hi membership prove kar deta hai','Public S3 website, aur har segment URL mein ek hi shared pakka password','CDN behavior ke bina S3 presigned URL, aur vaada wahi CDN edge permission ka'],3,'Signed cookies kai protected files cover kar sakti hain; app ki permission aur private origin phir bhi chahiye. OAC sirf origin ki taraf hai; public password kamzor hai; seedha S3 signature alag raasta hai.','secure'),
        Q('Viewer ka custom domain ACM use karta hai. Viewer certificate kahan request karein?','us-east-1 mein, matching alternate domain ke saath; origin ka certificate contract alag hai',['Sirf S3 bucket ke region mein, kyunki CDN poora origin region ke andar hi chalta hai','Kisi bhi region mein, kyunki CloudFront har ACM private key ko regions mein copy kar leta hai','Sirf viewer ke desh ke region mein, kyunki DNS source ki jagah certificate ka owner tay karti hai'],0,'CloudFront viewer ka ACM certificate us-east-1 mein hona chahiye. Origin ka cert kahin aur ho sakta hai; ACM apne aap copy nahi hota; viewer ka desh certificate ka region tay nahi karta.','secure'),
        Q('Login wali API ko CachingOptimized mil gaya, origin no-store bhejta hai. Review kiya hua safe behavior?','CachingDisabled + zaroori auth/query/cookie forwarding + origin ka sahi Host contract',['Minimum TTL 1 second rakho aur maan lo ki no-store hamesha shared cache entry rokta hai','Authorization forwarding hatao aur ek key par cache karo, taaki private jawaab tez aayein','SigningBehavior never wala naya OAC lagao, kyunki OAC hi API ki cache policy setting hai'],1,'MinimumTTL no-store ko override kar sakta hai. Cache band aur sahi forwarding chahiye; auth hatana aur shared key risky hai; OAC signing cache policy nahi.','secure'),
        Q('Sasta viewer URL rewrite, network ya body ki zaroorat nahi. Kya chunoge?','CloudFront Functions; runtime/code limits aur viewer event ka behaviour check karo',['Lambda@Edge zaroori hai, kyunki CloudFront Functions request URI badal hi nahi sakte','Regional RDS trigger, kyunki har CDN URI rewrite se pehle ek SQL transaction chahiye','Route53 weighted routing, kyunki DNS HTTP paths aur request headers dekhta hai'],2,'Functions halke viewer rewrites ke liye theek hai. Lambda@Edge zyada kar sakta hai par zaroori nahi; RDS ka lena-dena nahi; DNS HTTP path/header nahi dekhta.','high-performing'),
        Q('Emergency invalidation Completed hai. Phir bhi kuch browsers same URL par purani photo dikha rahe hain. Kyun?','Browser/office ka cache alag hai; versioned paths aur pointer refresh purane URL se bachate hain',['CloudFront Completed saare caches saaf karta hai, isliye browser naya IP dikha raha hoga','OAC browsers ko purane bytes par tab tak rokta hai jab tak service principal public na ho','Invalidation sirf cache hua HTML hata sakta hai; photos ko path se kabhi invalidate nahi kar sakte'],3,'CloudFront ki eviction aage ke caches saaf nahi karti. Completed poori duniya ke browsers ka control nahi; OAC browser ke bytes nahi pakadta; photo paths bhi invalidate ho sakte hain.','resilient'),
      ]},
    ],
    interview:{title:'🎤 CDN incident aur release review',instructions:'Cache ka matlab, permissions, concurrency aur saboot ki limits samjhao; aakhri kaam pehle se bane resources theek karta hai.',questions:[
      Q('Config ka ETag E1 liya, beech mein kisi aur ne update kiya, aur tumhara E1 wala update reject hua. Agla kadam?','Naya config/ETag dobara padho, apne badlav merge karo, aur doosron ka kaam mitaaye bina retry karo',['Purana poora config baar-baar retry karo, kyunki ETag sirf dikhawe ka field hai','Nakli disable-distribution operation chalao, taaki CloudFront concurrency check chupchaap chhod de','Private bucket delete karo, taaki distribution apne aap naya ETag chun le'],0,'ETag optimistic concurrency hai. Dobara padh kar merge karne se kisi ka update nahi khota; purana retry, nakli operation aur bucket delete config ka takraav safe tarike se nahi sulajhaate.','resilient'),
      Q('API ka jawaab ek header se badalta hai, jo shared cache key se bahar hai. Kya toot sakta hai?','Ek variant doosre viewer ko mil sakta hai; key ka design ya cache bypass jawaab ke matlab se match hona chahiye',['Har header value apne aap key mein jaati hai, chahe cache policy use saaf bahar rakhe','Origin request policy hamesha jawaab ke variants ko alag public cache entries mein encrypt karti hai','Zyada cache hit ratio prove karta hai ki permission sahi hai, chahe variants missing hon'],1,'Jawaab jis cheez se badalta hai, use safe tarike se key mein daalo, ya shared cache band karo. Forwarding apne aap key nahi banati; policies variants ko encrypt nahi karti; hit rate privacy ka saboot nahi.','secure'),
      Q('Pay-as-you-go mein 2,000 invalidation paths/mahina, pehle 1,000 free. Lagbhag kitna extra charge?','Lagbhag $5/mahina, 1,000 extra paths ka; viewer aur baaki features ka kharcha alag',['Lagbhag $10/mahina, kyunki mahine ke free paths par bhi baad mein 0.005 har path lagta hai','Lagbhag $50/mahina flat reservation, kyunki distribution disable hone par bhi deployed rehta hai','Kitne bhi paths par lagbhag $0/mahina, kyunki OAC invalidations ko unlimited bana deta hai'],2,'1,000 × $0.005 = $5. Free paths par baad mein charge nahi lagta; koi base reservation nahi; OAC pay-as-you-go invalidation quota nahi badalta.','cost-optimized'),
      Q('Private ALB origin chahiye. Aaj ke CloudFront mein kaunsa design?','Supported VPC origin, region, SG/ENI aur feature ki restrictions review karke',['Mumkin nahi, kyunki CloudFront ko har origin hamesha ke liye public chahiye hi','S3 OAC principal seedha ALB se jodo; saare network raaste aur TLS review ki zaroorat khatam','0.0.0.0/0 ingress wala public ALB apne aap prove karta hai ki origin bypass ruk gaya'],3,'VPC origins eligible private ALB/NLB/EC2 support karte hain. "Sirf public" wali baat purani hai; S3 OAC ALB ki routing nahi; public ingress bypass rukne ka saboot nahi.','secure'),
      {terminal:(function(){const a=seed(),d=a.cloudfront[0];d.config=fixed();d.config.CacheBehaviors.Items[0].CachePolicyId=OPT;d.etag='E7';d.version=7;a.originAccessControls=[{id:OAC,etag:'O1',config:control()}];a.cdnOacCounter=1;a.buckets[0].policy=policy();const tasks=[{text:'Pehle wala distribution deployed, /api/* CachingDisabled ke saath; S3/OAC bache rahe',check:deployed},{text:'Purani scoped service policy/BPA/object bache rahe',check:s=>scopeOK(s)&&preserved(s)},{text:'Targeted eviction Completed; naya v2 fixture',check:fresh}];const solution=['aws cloudfront update-distribution --id ESHOP --if-match E7 --distribution-config file://repair-config.json','aws cloudfront wait distribution-deployed --id ESHOP',"aws cloudfront create-invalidation --distribution-id ESHOP --paths '/img/kurta-red.jpg'",'aws cloudfront wait invalidation-completed --distribution-id ESHOP --id I000001'];return {title:'🖥️ Pehle wala OAC chalta hai; API cache aur purani file theek karo',goal:'Abhi ka ETag E7 hai. OAC aur scoped policy pehle se hain: dobara mat banao, public jugaad mat karo. cat repair-config.json padho, aaj ke poore config se update + deploy karo; same-path photo ki v1 edge copy invalidate karke Completed tak le jao. API ke data mein CachingDisabled aur review ki hui forwarding honi chahiye; asli API auth simulate nahi hota.',account:a,files:{'repair-config.json':file(fixed())},tasks,success:AG.allOf(tasks),solution,hints:solution.slice(),successText:'Origin ka pehle wala bachav bana raha; deployed API no-cache data aur poori hui purane bytes ki eviction match karte hain. App ki asli permission, Host/TLS aur browser freshness ke asli test abhi bhi chahiye.'};})()},
    ]},
    success:['CDN hit, origin permission, cache variant aur client freshness alag-alag samjha sakta hoon','S3 REST OAC policy aur viewer signed access ki boundaries chun sakta hoon','ETag conflict, deployment aur Completed invalidation ki state theek kar sakta hoon','Toy hit/latency/kharche ke andaaze aur AWS ke asli naape hue behaviour ka farak bata sakta hoon'],
    homework:'<p><b>Optional, sirf approved asli AWS sandbox mein (paisa lagega):</b> pehle pricing mode, jagah aur traffic ka andaaza lagao. Private test S3 REST bucket banao, ownership/BPA ke saath; supported OAC always/sigv4 aur scoped SourceArn policy set karo. Origin aur viewer ki permissions alag test karo: seedha anonymous S3 deny ho, approved CDN read chale, private viewer mein valid/expired signatures check hon. Asli Cache-Control/Age/X-Cache aur maange gaye paths dekho; safe versioned file + chhota manifest wala release dekho. Ek same-path fix ko target karke invalidate karo, Completed aur browser cache ka asli behaviour alag compare karo. Custom viewer cert us-east-1 mein; API origin ka header/auth/TLS contract review karo. Cleanup: test distribution ko naye poore config/ETag se disable karo, deployed hone tak wait karo, OAC hatao jahan theek ho, aur bucket se pehle test distribution delete karo; phir OAC, test objects/versions/bucket hatao, aur sirf test wali policy/certs/DNS/WAF/log/IP/plan resources review karke saaf karo. Pehle se bane/shared distributions, keys, policies aur origin resources ko mat chhuo.</p>',
    cards:[{front:'Cache policy vs origin request policy?',back:'Cache policy TTL aur key control karti hai. Key ki values origin tak bhi jaati hain; origin request policy extra inputs bhejti hai bina key mein daale. Jawaab ka badalna aur auth safe rehne chahiye.'},{front:'Private S3 ko CDN se padhne ke links?',back:'S3 REST origin + juda OAC always/sigv4 + scoped service GetObject/SourceArn policy + deployment. BPA ON rehta hai; KMS objects ke liye key permission bhi chahiye ho sakti hai.'},{front:'OAC vs signed URL/cookie?',back:'OAC: origin ke saamne pehchaan. App ka signed URL/cookie: trusted key groups se viewer ki permission. Sirf private origin se viewers paid-only nahi bante.'},{front:'Versioned file vs invalidation?',back:'Aam release: naya path + jaldi refresh hone wala HTML/manifest. Same path ka emergency: invalidate karo aur Completed tak wait karo. Browser/office ke caches CloudFront saaf nahi karta.'},{front:'Cache API safely?',back:'Sensitive dynamic API ke liye review kiya CachingDisabled + zaroori auth/cookie/query forwarding + origin ka Host/TLS. MinimumTTL>0 no-store ko override kar sakta hai.'},{front:'CloudFront custom viewer certificate kis region mein?',back:'ACM us-east-1 mein; alternate domain se match. Origin ka region/certificate alag; default CloudFront hostname ke paas pehle se certificate hai.'},{front:'Stale ETag update?',back:'PreconditionFailed: naya config/ETag dobara padho, merge karo, retry karo. Poora DistributionConfig update karo; deployment ka wait karo. Abhi ka Moto yeh precondition laagu nahi karta.'},{front:'High hit ratio matlab viewer bytes kam?',back:'Nahi. Origin ke fetches kam hote hain; viewer tak bytes phir bhi jaate hain. Pricing mode, jagah, allowance aur features maayne rakhte hain; disabled aam distribution ki koi base fees nahi.'}],
  }]);
})();
